import subprocess
import json
import pathlib

OUT = pathlib.Path("state/history")
OUT.mkdir(parents=True, exist_ok=True)


def git_show(path, commit="f26d62d"):
    r = subprocess.run(["git", "show", f"{commit}:{path}"], cwd="TokenCore_git",
                       capture_output=True, text=True, encoding="utf-8", errors="replace")
    if r.returncode != 0:
        print("FAIL", commit, path, r.stderr[:200])
        return None
    return r.stdout


for name in ["result.txt", "sms_result.txt", "sms_result1.txt"]:
    txt = git_show(name)
    if txt:
        (OUT / name).write_text(txt, encoding="utf-8")
        print("=" * 40, name)
        print(txt[:3000])

for name in ["test.ipynb", "test3.ipynb"]:
    txt = git_show(name)
    if txt is None:
        continue
    (OUT / name).write_text(txt, encoding="utf-8")
    nb = json.loads(txt)
    print("=" * 40, name, "n cells", len(nb["cells"]))
    for i, c in enumerate(nb["cells"]):
        if c["cell_type"] != "code":
