"""Metric layer: token-level and document-level AUROC / AUPRC (R5, R7)."""

import numpy as np
from sklearn.metrics import roc_auc_score, precision_recall_curve, auc, average_precision_score


def safe_auc(y, s, kind="roc"):
    y = np.asarray(y)
    if len(np.unique(y)) < 2:
        return float("nan")
    if kind == "roc":
        return float(roc_auc_score(y, s))
    return float(average_precision_score(y, s))


def prc_trapz(y, s):
    """AUPRC as in the authors' eval.py: auc(recall, precision) from
    precision_recall_curve (trapezoidal)."""
    y = np.asarray(y)
    if len(np.unique(y)) < 2:
        return float("nan")
    precision, recall, _ = precision_recall_curve(y, s)
    return float(auc(recall, precision))


def doc_scores(token_scores, doc_sizes, how="mean"):
    """Aggregate token scores to document scores (Eq. 3 mean, R5; 'max' as in the
    authors' notebooks for comparison)."""
    out = []
    start = 0
    for n in doc_sizes:
        chunk = np.asarray(token_scores[start:start + n], dtype=np.float64)
        start += n
        if n == 0:
            out.append(np.nan)
        elif how == "mean":
            out.append(float(chunk.mean()))
        elif how == "max":
            out.append(float(chunk.max()))
        else:
            raise ValueError(how)
    return np.asarray(out, dtype=np.float64)


def evaluate_split(token_scores, token_labels, doc_sizes, doc_labels):
    """All four metrics for one train/test split."""
    token_scores = np.asarray(token_scores, dtype=np.float64)
    token_labels = np.asarray(token_labels, dtype=int)
    res = {
        "token": {
            "auroc": safe_auc(token_labels, token_scores, "roc"),
            "auprc": safe_auc(token_labels, token_scores, "prc"),
            "auprc_trapz": prc_trapz(token_labels, token_scores),
        },
        "n_test_tokens": int(len(token_labels)),
        "n_positive_tokens": int(token_labels.sum()),
    }
    for how in ("mean", "max"):
        ds = doc_scores(token_scores, doc_sizes, how=how)
        res[f"document_{how}"] = {
            "auroc": safe_auc(doc_labels, ds, "roc"),
            "auprc": safe_auc(doc_labels, ds, "prc"),
            "auprc_trapz": prc_trapz(doc_labels, ds),
        }
    return res


def random_control(token_labels, doc_sizes, doc_labels, seed=0):
    """Sanity check: random token scores -> AUROC ~ 0.5."""
    rng = np.random.RandomState(seed)
    return evaluate_split(rng.rand(len(token_labels)), token_labels, doc_sizes,
                          doc_labels)


def metric_parity_check():
    """Metric plumbing check against sklearn on an independent synthetic problem."""
    from sklearn.metrics import roc_auc_score, precision_recall_curve, auc

    rng = np.random.RandomState(0)
    y = (rng.rand(500) < 0.1).astype(int)
    s = rng.rand(500) + 2.0 * y * rng.rand(500)
    p, r, _ = precision_recall_curve(y, s)
    assert abs(safe_auc(y, s, "roc") - roc_auc_score(y, s)) < 1e-12
    assert abs(prc_trapz(y, s) - auc(r, p)) < 1e-12
    return {"auroc": safe_auc(y, s, "roc"), "auprc_trapz": prc_trapz(y, s)}
